package com.bank.cheque;

import java.util.logging.Logger;

// Evaluates mixed increment expressions and reports the result + final counter.
class ExpressionTracer {
    private static final Logger log = Logger.getLogger(ExpressionTracer.class.getName());

    // Case A: x++ + ++x starting from 'start'
    int caseA(int start) {
        int x = start;
        int result = x++ + ++x; // left yields old, then right increments first
        log.fine(() -> "A: start=" + start + " result=" + result + " x=" + x);
        return result;
    }

    // Case B: ++x + x++ starting from 'start'
    int caseB(int start) {
        int x = start;
        int result = ++x + x++;
        log.fine(() -> "B: start=" + start + " result=" + result + " x=" + x);
        return result;
    }

    // Case C: x++ + x++ + ++x starting from 'start'
    int caseC(int start) {
        int x = start;
        int result = x++ + x++ + ++x;
        log.fine(() -> "C: start=" + start + " result=" + result + " x=" + x);
        return result;
    }

    // Case D: the self-assignment trap x = x++
    int caseD(int start) {
        int x = start;
        x = x++; // post-increment's OLD value is written back, cancelling the ++
        log.fine(() -> "D: start=" + start + " x=" + x);
        return x;
    }

    // Final x values for each case so we can report them cleanly.
    int finalXCaseA(int start) { int x = start; int r = x++ + ++x; return x; }
    int finalXCaseB(int start) { int x = start; int r = ++x + x++; return x; }
    int finalXCaseC(int start) { int x = start; int r = x++ + x++ + ++x; return x; }
}
