package com.bank.cheque;

import java.util.logging.*;

public class IncrementDemo {
    private static final Logger log = Logger.getLogger(IncrementDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ExpressionTracer t = new ExpressionTracer();

        int a = t.caseA(5);
        log.info(() -> "A: 5++ + ++? = x++ + ++x from 5 -> result " + a
                + ", final x = " + t.finalXCaseA(5));

        int b = t.caseB(5);
        log.info(() -> "B: ++x + x++ from 5 -> result " + b
                + ", final x = " + t.finalXCaseB(5));

        int c = t.caseC(1);
        log.info(() -> "C: x++ + x++ + ++x from 1 -> result " + c
                + ", final x = " + t.finalXCaseC(1));

        int d = t.caseD(10);
        log.warning(() -> "D: x = x++ from 10 -> x stays " + d
                + " (post-increment old value overwrites the increment)");

        // Business tie-in: a cheque counter used safely with SEPARATE statements.
        ChequeCounter counter = new ChequeCounter(1001);
        int firstCheque = counter.get(); counter.set(counter.get() + 1);
        int secondCheque = counter.get(); counter.set(counter.get() + 1);
        log.info(() -> "Clear batch: cheque1=" + firstCheque + ", cheque2=" + secondCheque
                + ", counter now " + counter.get());
    }
}

